export function BrowseStoragePage() {
  const [params, setParams] = useSearchParams()
  const location = params.get('location') || ''
  const size = params.get('size') || ''
  const type = params.get('type') || ''
  const startDate = params.get('startDate') || ''
  const availableOnly = params.get('available') === '1'
  const sort = params.get('sort') || ''
  const filtered = storageUnits.filter(unit => (!location || unit.location === location) && (!size || unit.size === size) && (!type || unit.type === type) && (!availableOnly || unit.available))
  if (sort) filtered.sort((a, b) => sort === 'price-desc' ? b.monthlyPrice - a.monthlyPrice : a.monthlyPrice - b.monthlyPrice)
  function change(key: string, value: string) { const next = new URLSearchParams(params); if (value) next.set(key, value); else next.delete(key); setParams(next, { replace: true }) }
  const query = startDate ? `?startDate=${encodeURIComponent(startDate)}` : ''
  return <Shell publicPage><div className="booking-heading mt-[26px] mb-[30px] mx-0 [&_h1]:mx-0 [&_h1]:my-2.5 [&_p]:text-[color:#64748b] [&_p]:text-[length:14px] max-[680px]:[&_p]:text-[length:12px]"><span className="booking-kicker text-[color:#2563eb] text-[length:10px] tracking-[1.4px] font-bold">SPACE FOR YOUR NEXT CHAPTER</span><h1>Find your storage</h1><p>Choose a location, size and start date to explore preview units.</p></div><div className="booking-filters bg-none bg-[color:white] bg-clip-border grid grid-cols-4 p-[22px] gap-[18px] rounded-[14px] border border-solid border-[color:#e2e8f0] [&_label]:flex [&_label]:flex-col [&_label]:text-[length:12px] [&_label]:font-semibold [&_label]:gap-2 max-[680px]:grid-cols-2 max-[680px]:p-4 max-[680px]:gap-[15px]"><label>Location<select value={location} onChange={e => change('location', e.target.value)}><option value="">All locations</option><option value="district-1">District 1</option><option value="thu-duc">Thu Duc</option></select></label><label>Size<select value={size} onChange={e => change('size', e.target.value)}><option value="">All sizes</option><option value="small">Small · 5 m²</option><option value="medium">Medium · 10 m²</option><option value="large">Large · 20 m²</option></select></label><label>Unit type<select value={type} onChange={e => change('type', e.target.value)}><option value="">All unit types</option><option value="standard">Standard</option><option value="cold">Cold storage</option></select></label><label>Start date<input type="date" value={startDate} min={localToday()} onChange={e => change('startDate', e.target.value)} onInput={e => change('startDate', e.currentTarget.value)} /></label></div><div className="booking-results-bar flex items-center justify-between text-[length:12px] text-[color:#475569] flex-wrap px-0 py-[23px] gap-6 max-[680px]:items-start max-[680px]:gap-[13px]"><span role="status">{filtered.length} matching preview units</span><label className={`booking-checkbox ${styles.bookingCheckbox}`}><input type="checkbox" checked={availableOnly} onChange={e => change('available', e.target.checked ? '1' : '')} />Available preview units only</label><label className="booking-sort flex items-center gap-2.5 [&_select]:w-[150px] max-[680px]:w-full max-[680px]:justify-between max-[680px]:[&_select]:w-[180px]">Sort<select value={sort} onChange={e => change('sort', e.target.value)}><option value="">Recommended</option><option value="price-asc">Price: low to high</option><option value="price-desc">Price: high to low</option></select></label></div>{filtered.length ? <div className="booking-unit-grid grid grid-cols-3 gap-6 max-[1000px]:grid-cols-2 max-[680px]:grid-cols-[1fr]">{filtered.map(unit => <UnitCard key={unit.id} unit={unit} query={query} />)}</div> : <div className={`booking-empty ${styles.bookingEmpty}`}><h2>No units match your filters</h2><p>Try a different location, size or unit type.</p><button className={`booking-button secondary ${styles.bookingButtonSecondary}`} onClick={() => setParams({})}>Clear filters</button></div>}</Shell>
}
