export function CustomerBookingsPage() {
  const { bookings, error, loading, refresh } = useBookings()
  const [status, setStatus] = useState('')
  const filtered = bookings.filter(b => !status || b.status === status)
  return <Shell><div className="booking-heading booking-heading-row flex items-center justify-between mx-0 my-7 gap-5 [&_h1]:mx-0 [&_h1]:my-2.5 [&_p]:text-[color:#64748b] [&_p]:text-[length:14px] max-[680px]:[&_p]:text-[length:12px] max-[680px]:items-start max-[680px]:flex-col max-[680px]:gap-[15px]"><div><span className="booking-kicker text-[color:#2563eb] text-[length:10px] tracking-[1.4px] font-bold">YOUR SPACE</span><h1>My Bookings</h1><p>Track your bookings and preview payment status.</p></div><Link className={`booking-button ${styles.bookingButtonSecondary}`} to="/storage">Book another unit →</Link></div><label className="booking-status-filter flex items-center text-[length:12px] mb-6 gap-3 [&_select]:max-w-[250px] max-[680px]:flex-col max-[680px]:items-start max-[680px]:[&_select]:max-w-none">Status<select value={status} onChange={e => setStatus(e.target.value)}><option value="">All bookings</option>{Object.entries(labels).map(([key, value]) => <option key={key} value={key}>{value}</option>)}</select></label>{loading ? <Loading /> : error ? <ErrorNotice message={error} retry={refresh} /> : filtered.length ? <div className="booking-order-list grid gap-5">{filtered.map(booking => <BookingCard key={booking.id} booking={booking} />)}</div> : <div className={`booking-empty ${styles.bookingEmpty}`}><h2>{bookings.length ? 'No bookings with this status' : 'No preview bookings yet'}</h2><p>Explore preview units and create your first booking.</p><Link className={`booking-button ${styles.bookingButtonSecondary}`} to="/storage">Find your storage</Link></div>}</Shell>
}
